void paint(){PAINTSTRUCT ps;HDC dc=BeginPaint(win,&ps);RECT client;GetClientRect(win,&client);FillRect(dc,&client,bg);RECT side={client.right-278,0,client.right,client.bottom};RECT tools={0,0,142,client.bottom};FillRect(dc,&tools,panel);FillRect(dc,&side,panel);SetBkMode(dc,TRANSPARENT);SetTextColor(dc,RGB(235,240,250));SelectObject(dc,titleFont);TextOut(dc,client.right-256,20-sidebarOffset,L"PhotoMaster AI",14);SelectObject(dc,font);SetTextColor(dc,RGB(145,156,179));TextOut(dc,client.right-255,54-sidebarOffset,L"ЛОКАЛЬНЫЙ ФОТОРЕДАКТОР",(int)wcslen(L"ЛОКАЛЬНЫЙ ФОТОРЕДАКТОР"));view={154,42,client.right-292,client.bottom-62};FillRect(dc,&view,bg);if(!img.empty()){const Photo &im=before?orig:(previewActive?preview:img);double scale=std::min((view.right-view.left)/(double)im.w,(view.bottom-view.top)/(double)im.h);scale*=zoom;vw=std::max(1,(int)(im.w*scale));vh=std::max(1,(int)(im.h*scale));vx=view.left+(view.right-view.left-vw)/2+panX;vy=view.top+(view.bottom-view.top-vh)/2+panY;Graphics g(dc);g.SetClip(Rect(view.left,view.top,view.right-view.left,view.bottom-view.top));for(int yy=std::max(vy,(int)view.top);yy<std::min(vy+vh,(int)view.bottom);yy+=16)for(int xx=std::max(vx,(int)view.left);xx<std::min(vx+vw,(int)view.right);xx+=16){SolidBrush brush(((xx-vx)/16+(yy-vy)/16)%2?Color(255,61,65,76):Color(255,49,53,63));g.FillRectangle(&brush,xx,yy,std::min(16,vx+vw-xx),std::min(16,vy+vh-yy));}Bitmap bitmap(im.w,im.h,im.w*4,PixelFormat32bppARGB,(BYTE*)im.p.data());g.SetInterpolationMode(InterpolationModeHighQualityBicubic);g.DrawImage(&bitmap,vx,vy,vw,vh);if(centerMode){Pen pen(Color(255,140,125,255),2);float cx=vx+centerX*vw,cy=vy+centerY*vh;g.DrawLine(&pen,cx-18,cy,cx+18,cy);g.DrawLine(&pen,cx,cy-18,cx,cy+18);}if(dragging&&tool==4){Pen pen(Color(255,180,190,255),1);g.DrawRectangle(&pen,(int)std::min(dragStart.x,dragEnd.x),(int)std::min(dragStart.y,dragEnd.y),(int)abs(dragEnd.x-dragStart.x),(int)abs(dragEnd.y-dragStart.y));}SetTextColor(dc,RGB(200,205,220));TextOut(dc,view.left,client.bottom-52,before?L"ОРИГИНАЛ • ДО":L"РЕЗУЛЬТАТ • ПОСЛЕ",before?(int)wcslen(L"ОРИГИНАЛ • ДО"):(int)wcslen(L"РЕЗУЛЬТАТ • ПОСЛЕ"));}else{SetTextColor(dc,RGB(208,216,236));RECT text=view;DrawText(dc,L"Перетащите фотографию сюда\n\nили нажмите «Открыть фото»\n\nJPG · PNG · BMP · TIFF\n\nВсе фотографии остаются на вашем компьютере",-1,&text,DT_CENTER|DT_WORDBREAK);}EndPaint(win,&ps);}
